Given two sorted arrays a[] and b[] of size n and m respectively, merge both the arrays and rearrange the elements such that the smallest n elements are in a[] and the remaining m elements are in b[]. All elements in a[] and b[] should be in sorted order.Examples: Input: a[] = [2, 4, 7, 10], b[] = [2, 3]Output: a[] = [2, 2, 3, 4], b[] = [7, 10] Explanation: Combined sorted array = [2, 2, 3, 4, 7, 10], array a[] contains smallest 4 elements: 2, 2, 3 and 4, and array b[] contains remaining 2 elements: 7, 10.Input: a[] = [1, 5, 9, 10, 15, 20], b[] = [2, 3, 8, 13]Output: a[] = [1, 2, 3, 5, 8, 9], b[] = [10, 13, 15, 20]Explanation: Combined sorted array = [1, 2, 3, 5, 8, 9, 10, 13, 15, 20], array a[] contains smallest 6 elements: 1, 2, 3, 5, 8 and 9, and array b[] contains remaining 4 elements: 10, 13, 15, 20.Input: a[] = [0, 1], b[] = [2, 3]Output: a[] = [0, 1], b[] = [2, 3] Explanation: Combined sorted array = [0, 1, 2, 3], array a[] contains smallest 2 elements: 0 and 1, and array b[] contains remaining 2 elements: 2 and 3.Try It YourselfTable of ContentUsing Insert of Insertion SortUsing n-th smallest elementBy Swap and SortUsing Gap method [Naive Approach] Using Insert of Insertion SortThe idea is to traverse b[] from the end in reverse order and compare each element with the last (largest) element of a[]. For any index i, if b[i] is smaller than the last element of a[], replace b[i] with the last element of a[] and use insert step of insertion sort to find the correct place of b[i] in a[].How do we keep a[] sorted? Every time we add any element from b[] to a[], we find the correct index using insert step of insertion sort.How do we keep b[] sorted? This is ensured by the fact that we traverse b[] from end and insert only when current element of b[] is smaller.Illustration 
            C++

    #include <iostream>
#include <vector>
using namespace std;

void mergeArrays(vector<int>& a, vector<int>& b) {

  	// Traverse b[] starting from the last element
    for (int i = b.size() - 1; i >= 0; i--) {

        // If b[i] is smaller than the largest element of a[]
        if (a.back() > b[i]) {

          	// Place b[i] in the correct position in a[], 
            // and move last element of a[] to b[]
            int last = a.back();
          	int j = a.size() - 2;
            while (j >= 0 && a[j] > b[i]) {
                a[j + 1] = a[j];
                j--;
            }

            a[j + 1] = b[i];
            b[i] = last;
        }
    }
}

int main() {
    vector<int> a = {1, 5, 9, 10, 15, 20};
    vector<int> b = {2, 3, 8, 13};
    mergeArrays(a, b);

    for (int ele: a)
        cout << ele << " ";
    cout << "\n";
    for (int ele: b)
        cout << ele << " ";
    return 0;
}


